KG42.register("rules-f3c3d994914af7726d57e6db",{"id":"42-data_center_space_time_flexibility::v141-c-R003","paper":"42-data_center_space_time_flexibility","record":{"rule_id":"v141-c-R003","mechanism_id":"v141-a-M01","name":"Social-welfare clearing objective","process_stage":"clearing","market_meaning":"The maximum requested quantity submitted by a consumer limits its allocation in welfare clearing. Scope: Static market with inflexible consumers; each consumer's cleared withdrawal. The available quantity offered by a supplier limits its allocation in welfare clearing. Scope: Static market with inflexible consumers; each supplier's cleared injection. Welfare clearing maximizes the value of served demand net of supply and transmission-service costs. Scope: Basic static market clearing with inflexible consumers. Welfare-clearing allocations must satisfy nodal power balance, DC power-flow equations and the stated phase-angle and flow-capacity constraints. Scope: Physical-network feasibility of the static welfare-clearing allocations.","independence_rationale":"Relations governed by the approved function clearing.social_welfare under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","clearing.social_welfare"],"E":[{"edge_id":"v141-c-R003-E001","source":"bidding.demand","target":"clearing.social_welfare","type":"limits","constraint_ids":["v141-c-R003-C001"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e016"]},{"edge_id":"v141-c-R003-E002","source":"bidding.supply","target":"clearing.social_welfare","type":"limits","constraint_ids":["v141-c-R003-C002"],"evidence_ids":["v141-b-g01-e008","v141-b-g01-e016"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Basic static market clearing with inflexible consumers. | Physical-network feasibility of the static welfare-clearing allocations. | Static market with inflexible consumers; each consumer's cleared withdrawal. | Static market with inflexible consumers; each supplier's cleared injection.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e008","v141-b-g01-e009","v141-b-g01-e013","v141-b-g01-e014","v141-b-g01-e016","v141-b-g01-e022"]},"x":[{"variable_id":"v141-c-R003-x-d","symbol":"d_j","meaning":"Cleared load withdrawal of consumer j in welfare clearing.","kind":"operational","domain":"0 \\le d_j \\le \\bar{d}_j for all j \\in \\mathcal{D}","unit":null,"indices":["j \\in \\mathcal{D}"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e016"]},{"variable_id":"v141-c-R003-x-p","symbol":"p_i","meaning":"Cleared power injection of supplier i in welfare clearing.","kind":"operational","domain":"0 \\le p_i \\le \\bar{p}_i for all i \\in \\mathcal{S}","unit":null,"indices":["i \\in \\mathcal{S}"],"evidence_ids":["v141-b-g01-e008","v141-b-g01-e016"]},{"variable_id":"v141-c-R003-x-f","symbol":"f_l","meaning":"Cleared power flow on transmission line l in welfare clearing.","kind":"operational","domain":"-\\bar f_l \\le f_l \\le \\bar f_l for all l \\in \\mathcal{L}","unit":null,"indices":["l \\in \\mathcal{L}"],"evidence_ids":["v141-b-g01-e012","v141-b-g01-e013","v141-b-g01-e014","v141-b-g01-e016"]},{"variable_id":"v141-c-R003-x-theta","symbol":"\\theta_n","meaning":"Phase angle at node n in the DC network representation used by welfare clearing.","kind":"operational","domain":"\\theta_n \\in \\mathbb{R}; phase-angle differences are bounded as stated in the clearing constraints","unit":null,"indices":["n \\in \\mathcal{N}"],"evidence_ids":["v141-b-g01-e013","v141-b-g01-e014","v141-b-g01-e016"]}],"theta":[{"parameter_id":"v141-c-R003-theta-alpha-d","symbol":"\\alpha^{d}_{j}","meaning":"Bid price submitted by consumer j for requested power.","value":{"kind":"symbolic","number_value":null,"text_value":"\\alpha^{d}_{j}\\in\\mathbb{R}_{+}"},"unit":null,"indices":["j \\in \\mathcal{D}"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e016"]},{"parameter_id":"v141-c-R003-theta-dbar","symbol":"\\bar{d}_j","meaning":"Maximum requested capacity submitted by consumer j.","value":{"kind":"symbolic","number_value":null,"text_value":"\\bar{d}_j\\in[0,\\infty)"},"unit":null,"indices":["j \\in \\mathcal{D}"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e016"]},{"parameter_id":"v141-c-R003-theta-alpha-p","symbol":"\\alpha^{p}_{i}","meaning":"Bid price submitted by supplier i for offered power.","value":{"kind":"symbolic","number_value":null,"text_value":"\\alpha^{p}_{i}\\in\\mathbb{R}_{+}"},"unit":null,"indices":["i \\in \\mathcal{S}"],"evidence_ids":["v141-b-g01-e008","v141-b-g01-e016"]},{"parameter_id":"v141-c-R003-theta-pbar","symbol":"\\bar{p}_i","meaning":"Available generation capacity offered by supplier i.","value":{"kind":"symbolic","number_value":null,"text_value":"\\bar{p}_i\\in[0,\\infty)"},"unit":null,"indices":["i \\in \\mathcal{S}"],"evidence_ids":["v141-b-g01-e008","v141-b-g01-e016"]},{"parameter_id":"v141-c-R003-theta-alpha-f","symbol":"\\alpha^{f}_{l}","meaning":"Bid price of transmission line l for transmission service.","value":{"kind":"symbolic","number_value":null,"text_value":"\\alpha^{f}_{l}\\in\\mathbb{R}_{+}"},"unit":null,"indices":["l \\in \\mathcal{L}"],"evidence_ids":["v141-b-g01-e012","v141-b-g01-e016"]},{"parameter_id":"v141-c-R003-theta-fbar","symbol":"\\bar{f}_l","meaning":"Flow-capacity limit of transmission line l.","value":{"kind":"symbolic","number_value":null,"text_value":"\\bar{f}_l\\in[0,\\infty)"},"unit":null,"indices":["l \\in \\mathcal{L}"],"evidence_ids":["v141-b-g01-e012","v141-b-g01-e014","v141-b-g01-e016"]},{"parameter_id":"v141-c-R003-theta-B","symbol":"B_l","meaning":"Susceptance of transmission line l in the DC power-flow model.","value":{"kind":"symbolic","number_value":null,"text_value":"B_l\\in\\mathbb{R}_{+}"},"unit":null,"indices":["l \\in \\mathcal{L}"],"evidence_ids":["v141-b-g01-e013","v141-b-g01-e014","v141-b-g01-e016"]},{"parameter_id":"v141-c-R003-theta-DeltaThetaBar","symbol":"\\bar{\\Delta\\theta}_l","meaning":"Effective maximum phase-angle difference on line l, defined in the source as the minimum of the flow-implied and angle-implied bounds.","value":{"kind":"symbolic","number_value":null,"text_value":"\\min\\{\\bar f_l/B_l,\\bar{\\Delta\\theta}'_l\\}"},"unit":null,"indices":["l \\in \\mathcal{L}"],"evidence_ids":["v141-b-g01-e014","v141-b-g01-e016"]},{"parameter_id":"v141-c-R003-theta-DeltaThetaPrimeBar","symbol":"\\bar{\\Delta\\theta}'_l","meaning":"Source-defined small phase-angle-difference limit for line l in the DC model.","value":{"kind":"symbolic","number_value":null,"text_value":"\\bar{\\Delta\\theta}'_l"},"unit":null,"indices":["l \\in \\mathcal{L}"],"evidence_ids":["v141-b-g01-e014"]}],"phi":[{"constraint_id":"v141-c-R003-C001","kind":"mathematical","role":"core","statement":"The maximum requested quantity submitted by a consumer limits its allocation in welfare clearing. Scope: Static market with inflexible consumers; each consumer's cleared withdrawal.","expression":"0 \\le d_j \\le \\bar{d}_j, \\quad \\forall j\\in\\mathcal{D}","formalization_origin":"source","template_id":null,"members":["bidding.demand","clearing.social_welfare"],"variable_refs":["v141-c-R003-x-d"],"parameter_refs":["v141-c-R003-theta-dbar"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e016"]},{"constraint_id":"v141-c-R003-C002","kind":"mathematical","role":"core","statement":"The available quantity offered by a supplier limits its allocation in welfare clearing. Scope: Static market with inflexible consumers; each supplier's cleared injection.","expression":"0 \\le p_i \\le \\bar{p}_i, \\quad \\forall i\\in\\mathcal{S}","formalization_origin":"source","template_id":null,"members":["bidding.supply","clearing.social_welfare"],"variable_refs":["v141-c-R003-x-p"],"parameter_refs":["v141-c-R003-theta-pbar"],"evidence_ids":["v141-b-g01-e008","v141-b-g01-e016"]},{"constraint_id":"v141-c-R003-C003","kind":"mathematical","role":"core","statement":"Welfare clearing maximizes the value of served demand net of supply and transmission-service costs. Scope: Basic static market clearing with inflexible consumers.","expression":"\\max_{d,p,f,\\theta}\\ \\sum_{j\\in\\mathcal{D}}\\alpha^{d}_{j}d_j-\\sum_{i\\in\\mathcal{S}}\\alpha^{p}_{i}p_i-\\sum_{l\\in\\mathcal{L}}\\alpha^{f}_{l}|f_l|","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R003-x-d","v141-c-R003-x-p","v141-c-R003-x-f","v141-c-R003-x-theta"],"parameter_refs":["v141-c-R003-theta-alpha-d","v141-c-R003-theta-alpha-p","v141-c-R003-theta-alpha-f"],"evidence_ids":["v141-b-g01-e016","v141-b-g01-e022"]},{"constraint_id":"v141-c-R003-C004","kind":"mathematical","role":"core","statement":"Welfare-clearing allocations must satisfy nodal power balance, DC power-flow equations and the stated phase-angle and flow-capacity constraints. Scope: Physical-network feasibility of the static welfare-clearing allocations.","expression":"\\sum_{l\\in\\mathcal{L}^{rec}_n} f_l+\\sum_{i\\in\\mathcal{S}_n} p_i=\\sum_{l\\in\\mathcal{L}^{snd}_n} f_l+\\sum_{j\\in\\mathcal{D}_n} d_j,\\ \\forall n\\in\\mathcal{N};\\quad f_l=B_l(\\theta_{snd(l)}-\\theta_{rec(l)}),\\ \\forall l\\in\\mathcal{L};\\quad -\\bar{\\Delta\\theta}_l\\le \\theta_{rec(l)}-\\theta_{snd(l)}\\le \\bar{\\Delta\\theta}_l,\\ \\forall l\\in\\mathcal{L};\\quad -\\bar f_l\\le f_l\\le \\bar f_l,\\ \\forall l\\in\\mathcal{L}","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R003-x-d","v141-c-R003-x-p","v141-c-R003-x-f","v141-c-R003-x-theta"],"parameter_refs":["v141-c-R003-theta-fbar","v141-c-R003-theta-B","v141-c-R003-theta-DeltaThetaBar"],"evidence_ids":["v141-b-g01-e012","v141-b-g01-e013","v141-b-g01-e014","v141-b-g01-e016"]}],"pi":[{"evidence_id":"v141-b-g01-e008","location":{"location_id":"src-1c03246cb9-p03-c1r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":"2.1 Basic notation and terminology","anchor_text":"We begin our discussion by introducing basic notation for a static to network (there is no time asso","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"Each supplier i \\in \\mathcal{S} is connected to the power grid at node n(i) \\in \\mathcal{N}. The supplier bids into the market by offering power at bid price \\alpha^{p}_{i} \\in \\mathbb{R}_{+} and offers available capacity \\bar{p}_{i} \\in [0,\\infty). We define \\mathcal{S}_{n} := \\{i \\in \\mathcal{S} | n(i)=n\\} \\subseteq \\mathcal{S} (set of suppliers connected to node n). The cleared allocation for supplier i \\in \\mathcal{S} (load injected) are denoted as p_i and must satisfy p_i \\in [0,\\bar{p}_{i}]. We use p to denote the collection of all cleared allocations."},{"evidence_id":"v141-b-g01-e009","location":{"location_id":"src-1c03246cb9-p03-c1r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":"2.1 Basic notation and terminology","anchor_text":"We begin our discussion by introducing basic notation for a static to network (there is no time asso","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"A consumer j \\in \\mathcal{D} bids into the market by requesting power at bid price \\alpha^{d}_{j} \\in \\mathbb{R}_{+} and requests a maximum capacity \\bar{d}_{j} \\in [0,\\infty). We define \\mathcal{D}_{n} := \\{j \\in \\mathcal{D} | n(j)=n\\} \\subseteq \\mathcal{D} (set of consumers connected to node n). For simplicity, we assume that there is only one consumer at a given node (\\mathcal{D}_{n} are singletons). The cleared allocation for consumer j \\in \\mathcal{D} (load withdrawn) is denoted as d_j and must satisfy d_j \\in [0,\\bar{d}_{j}]. We use d to denote the collection of all cleared allocations."},{"evidence_id":"v141-b-g01-e013","location":{"location_id":"src-1c03246cb9-p03-c2r2__v141-a-M01-pricing","page":3,"printed_page":null,"section":"2.1 Basic notation and terminology","anchor_text":"at collection 𝑓must obey the direct-current (DC) power flow equations: 4 𝑓𝑙= 𝐵𝑙(𝜃snd(𝑙) −𝜃rec(𝑙)), (","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"... the collection f must obey the direct-current (DC) power flow equations: f_l = B_l(\\theta_{snd(l)}-\\theta_{rec(l)}), \\quad (2.1) where B_l \\in \\mathbb{R}_{+} is the line susceptance and \\theta_n \\in \\mathbb{R} is the phase angle at node n \\in \\mathcal{N}."},{"evidence_id":"v141-b-g01-e014","location":{"location_id":"src-1c03246cb9-p03-c2r2__v141-a-M01-pricing","page":3,"printed_page":null,"section":"2.1 Basic notation and terminology","anchor_text":"at collection 𝑓must obey the direct-current (DC) power flow equations: 4 𝑓𝑙= 𝐵𝑙(𝜃snd(𝑙) −𝜃rec(𝑙)), (","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The DC power flow model is a linear model and requires small phase angle differences across transmission lines \\theta_{snd(l)}-\\theta_{rec(l)} \\in [-\\bar{\\Delta\\theta}'_{l},\\bar{\\Delta\\theta}'_{l}]. The limits on phase angle differences and the capacity constraints for flows can be captured as: -\\bar{\\Delta\\theta}_{l} \\le \\theta_{snd(l)}-\\theta_{rec(l)} \\le \\bar{\\Delta\\theta}_{l} \\quad (2.2) where \\bar{\\Delta\\theta}_{l} := \\min\\{\\bar{f}_{l}/B_l,\\bar{\\Delta\\theta}'_{l}\\}."},{"evidence_id":"v141-b-g01-e016","location":{"location_id":"src-1c03246cb9-p03-c2r3__v141-a-M01-clearing","page":3,"printed_page":null,"section":"2.2 Basic formulation with inflexible consumers","anchor_text":"ic to be delivered at different locations); as such, a well-designed market a should properly remune","equation_id":"2.3","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"We begin our discussion by studying a clearing formulation with inflexible consumers: \\max_{d,p,f,\\theta} \\sum_{j\\in\\mathcal{D}}\\alpha^{d}_{j}d_{j}-\\sum_{i\\in\\mathcal{S}}\\alpha^{p}_{i}p_{i}-\\sum_{l\\in\\mathcal{L}}\\alpha^{f}_{l}|f_{l}| \\quad (2.3a) s.t. \\sum_{l\\in\\mathcal{L}^{rec}_{n}} f_{l}+\\sum_{i\\in\\mathcal{S}_{n}}p_{i}=\\sum_{l\\in\\mathcal{L}^{snd}_{n}}f_{l}+\\sum_{j\\in\\mathcal{D}_{n}}d_{j},\\quad (\\pi_n)\\ n\\in\\mathcal{N} \\quad (2.3b) f_{l}=B_{l}(\\theta_{snd(l)}-\\theta_{rec(l)}),\\quad l\\in\\mathcal{L} \\quad (2.3c) d\\in C_{d},\\ p\\in C_{p},\\ \\theta\\in C_{\\theta} \\quad (2.3d). Here, we define the feasible capacity sets C_{d}:=\\{d| d_{j}\\in[0,\\bar{d}_{j}]\\ \\forall j\\in\\mathcal{D}\\}, C_{p}:=\\{p| p_{i}\\in[0,\\bar{p}_{i}]\\ \\forall i\\in\\mathcal{S}\\} and C_{\\theta}:=\\{\\theta| \\theta_{rec(l)}-\\theta_{snd(l)}\\in[-\\bar{\\Delta\\theta}_{l},\\bar{\\Delta\\theta}_{l}]\\ \\forall l\\in\\mathcal{L}\\}. The objective function (2.3a) is known as the social surplus or total welfare, which captures the value of demand served (to be maximized) and the cost of supply and transmission cost services (to be minimized). ... Constraint (2.3b) is the power balance constraint at each node n (Kirchhoff's current law)."},{"evidence_id":"v141-b-g01-e022","location":{"location_id":"src-1c03246cb9-p04-c1r3__v141-a-M01-clearing","page":4,"printed_page":null,"section":"2.2 Basic formulation with inflexible consumers","anchor_text":"∑ ∑ ∑ min 𝛼𝑝𝑖𝑝𝑖+ 𝛼𝑓𝑘𝑓𝑘− 𝛼𝑑𝑗𝑑𝑗 (2.7a)𝑑,𝑝,𝑓,𝜃 𝑖∈ 𝑘∈ 𝑗∈ ∑ ∑ ∑ ∑ s.t. 𝑓𝑘+ 𝑝𝑖= 𝑓𝑘+ 𝑑𝑗, (𝜋𝑛) 𝑛∈ (2.7b)","equation_id":"2.7","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"This leads to the (equivalent) clearing problem: \\min_{d,p,f,\\theta} \\sum_{i\\in\\mathcal{S}}\\alpha^{p}_{i}p_{i}+\\sum_{k\\in\\mathcal{K}}\\alpha^{f}_{k}f_{k}-\\sum_{j\\in\\mathcal{D}}\\alpha^{d}_{j}d_{j} \\quad (2.7a) s.t. \\sum_{k\\in\\mathcal{K}^{rec}_{n}}f_{k}+\\sum_{i\\in\\mathcal{S}_{n}}p_{i}=\\sum_{k\\in\\mathcal{K}^{snd}_{n}}f_{k}+\\sum_{j\\in\\mathcal{D}_{n}}d_{j},\\quad (\\pi_n)\\ n\\in\\mathcal{N} \\quad (2.7b) f_{l^{+}}-f_{l^{-}}=B_{l}(\\theta_{snd(l)}-\\theta_{rec(l)}),\\quad l\\in\\mathcal{L} \\quad (2.7c) d\\in C_{d},\\ p\\in C_{p},\\ \\theta\\in C_{\\theta} \\quad (2.7d). In this formulation, we minimize the negative surplus (as opposed to maximize the surplus); this equivalent representation will facilitate the analysis."},{"evidence_id":"v141-b-g01-e012","location":{"location_id":"src-1c03246cb9-p03-c2r1__v141-a-M01-bidding","page":3,"printed_page":null,"section":"2.1 Basic notation and terminology","anchor_text":"Applied Energy 326 (2022) 119930 r- Each transmission owner has a line 𝑙∈defined by its sending a n","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"Each transmission owner has a line l \\in \\mathcal{L} defined by its sending node snd(l) \\in \\mathcal{N} and receiving node rec(l) \\in \\mathcal{N}. The definitions of snd(l) and rec(l) are interchangeable because power can flow in either direction. The sending and receiving nodes of a link are also known as its supporting nodes. For each node n \\in \\mathcal{N}, we define its set of receiving lines \\mathcal{L}^{rec}_{n} := \\{l \\in \\mathcal{L} | n=rec(l)\\} \\subseteq \\mathcal{L} and its set of sending lines \\mathcal{L}^{snd}_{n} := \\{l \\in \\mathcal{L} | n=snd(l)\\} \\subseteq \\mathcal{L}. Each line offers a bid price \\alpha^{f}_{l} \\in \\mathbb{R}_{+} and capacity \\bar{f}_{l} \\in [0,\\infty). Note that while in common market clearing practice, transmission line costs are not captured (i.e., \\alpha^{f}_{l}=0 for each line l), we add this generality in order to demonstrate the similarity between transmission network and flexibility network later. Each cleared flow f_l must satisfy the bounds f_l \\in [-\\bar{f}_{l},\\bar{f}_{l}] ..."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"clearing.social_welfare","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e009","quote":"requests a maximum capacity \\bar{d}_{j} \\in [0,\\infty)."},{"evidence_id":"v141-b-g01-e009","quote":"The cleared allocation for consumer j \\in \\mathcal{D} (load withdrawn) is denoted as d_j and must satisfy d_j \\in [0,\\bar{d}_{j}]."},{"evidence_id":"v141-b-g01-e016","quote":"The objective function (2.3a) is known as the social surplus or total welfare"}],[{"evidence_id":"v141-b-g01-e008","quote":"offers available capacity \\bar{p}_{i} \\in [0,\\infty)."},{"evidence_id":"v141-b-g01-e008","quote":"The cleared allocation for supplier i \\in \\mathcal{S} (load injected) are denoted as p_i and must satisfy p_i \\in [0,\\bar{p}_{i}]."},{"evidence_id":"v141-b-g01-e016","quote":"The objective function (2.3a) is known as the social surplus or total welfare"}],[{"evidence_id":"v141-b-g01-e016","quote":"The objective function (2.3a) is known as the social surplus or total welfare, which captures the value of demand served (to be maximized) and the cost of supply and transmission cost services (to be minimized)."},{"evidence_id":"v141-b-g01-e022","quote":"In this formulation, we minimize the negative surplus (as opposed to maximize the surplus); this equivalent representation will facilitate the analysis."}],[{"evidence_id":"v141-b-g01-e016","quote":"Constraint (2.3b) is the power balance constraint at each node n (Kirchhoff's current law)."},{"evidence_id":"v141-b-g01-e013","quote":"the collection f must obey the direct-current (DC) power flow equations"},{"evidence_id":"v141-b-g01-e014","quote":"The limits on phase angle differences and the capacity constraints for flows can be captured as: -\\bar{\\Delta\\theta}_{l} \\le \\theta_{snd(l)}-\\theta_{rec(l)} \\le \\bar{\\Delta\\theta}_{l} \\quad (2.2)"}]],"C2_formalization":{"graph_sha256":"00cd76ba551113525d07aeef61720870810f0e8b9214ff49b0675a5f61404e7b","applicability":"formalized","reason":"The rule is formalized from source equations (2.3a)-(2.3d), with equivalent form (2.7), and from the verified source definitions of cleared withdrawals, cleared injections, DC flows, and phase-angle limits. B evidence remains unreviewed; no independent source audit is asserted.","bindings":[{"object_id":"v141-c-R003-x-d","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R003-E001"],"rationale":"The cleared withdrawal d_j is decided in welfare clearing and is constrained by the consumer's bid capacity under bidding.demand; E001 is the explicit limits edge."},{"object_id":"v141-c-R003-x-p","node_ids":["bidding.supply","clearing.social_welfare"],"edge_ids":["v141-c-R003-E002"],"rationale":"The cleared injection p_i is decided in welfare clearing and is constrained by the supplier's offered capacity under bidding.supply; E002 is the explicit limits edge."},{"object_id":"v141-c-R003-x-f","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Line flows are clearing variables in the welfare formulation. The frozen graph has no separate transmission node for this rule, so f_l is bound to clearing.social_welfare where the DC flow and flow-bound constraints appear."},{"object_id":"v141-c-R003-x-theta","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Nodal phase angles are clearing variables in the DC representation. The frozen graph has no separate network node for this rule, so theta_n is bound to clearing.social_welfare."},{"object_id":"v141-c-R003-theta-alpha-d","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":[],"rationale":"Consumer bid price alpha^d_j originates in demand bidding and enters the welfare objective."},{"object_id":"v141-c-R003-theta-dbar","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R003-E001"],"rationale":"The maximum requested quantity bar d_j is the demand-side parameter that caps d_j; E001 represents this limit from bidding.demand to clearing.social_welfare."},{"object_id":"v141-c-R003-theta-alpha-p","node_ids":["bidding.supply","clearing.social_welfare"],"edge_ids":[],"rationale":"Supplier bid price alpha^p_i originates in supply bidding and enters the welfare objective."},{"object_id":"v141-c-R003-theta-pbar","node_ids":["bidding.supply","clearing.social_welfare"],"edge_ids":["v141-c-R003-E002"],"rationale":"The available capacity bar p_i is the supply-side parameter that caps p_i; E002 represents this limit from bidding.supply to clearing.social_welfare."},{"object_id":"v141-c-R003-theta-alpha-f","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Line bid price alpha^f_l appears in the welfare objective's transmission-service cost. The frozen graph has no separate transmission-provider node for this rule, so it is bound to clearing.social_welfare."},{"object_id":"v141-c-R003-theta-fbar","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Flow-capacity limit bar f_l constrains line flows in the welfare formulation and is bound to clearing.social_welfare."},{"object_id":"v141-c-R003-theta-B","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"Line susceptance B_l defines the DC power-flow equation inside welfare clearing and is bound to clearing.social_welfare."},{"object_id":"v141-c-R003-theta-DeltaThetaBar","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"The effective phase-angle bound bar Delta theta_l constrains theta in the welfare formulation and is bound to clearing.social_welfare."},{"object_id":"v141-c-R003-theta-DeltaThetaPrimeBar","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"The source small-angle limit bar Delta theta'_l contributes to the effective phase-angle bound in the welfare formulation and is bound to clearing.social_welfare."},{"object_id":"v141-c-R003-C001","node_ids":["bidding.demand","clearing.social_welfare"],"edge_ids":["v141-c-R003-E001"],"rationale":"C001 formalizes the demand-capacity limit on cleared withdrawal, exactly the relation represented by E001 from bidding.demand to clearing.social_welfare."},{"object_id":"v141-c-R003-C002","node_ids":["bidding.supply","clearing.social_welfare"],"edge_ids":["v141-c-R003-E002"],"rationale":"C002 formalizes the supply-capacity limit on cleared injection, exactly the relation represented by E002 from bidding.supply to clearing.social_welfare."},{"object_id":"v141-c-R003-C003","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"C003 is the social-welfare objective owned by clearing.social_welfare; its decision variables and bid parameters are bound separately to the relevant graph nodes."},{"object_id":"v141-c-R003-C004","node_ids":["clearing.social_welfare"],"edge_ids":[],"rationale":"C004 states the physical feasibility constraints of the welfare-clearing allocation and is bound to clearing.social_welfare, the rule's clearing node."}],"revision_requests":[]}},"quarantined_references":[]}});
